"""The calendar library: the design's date-picker building blocks, as widgets.

calendar.html draws its picker panels from a handful of pieces: a row of
quick dates, a row of duration chips, a time row, a list of presets and a
summary of the range picked. Each is a :class:`Component` here, composed
from the SDK's own primitives, so a page drops one in and gets the design::

    from workpeg.ui.calendar import QuickRanges, TimeRow

    CalendarCard(
        QuickRanges(on_change=self.set_day),
        CalendarDatePicker(value=self.day, on_change=self.set_day,
                           surface="flat"),
        TimeRow("Time", value=self.at, on_change=self.set_at),
    )

The design's assembled panels are here too, ready to drop in: a date and
a time (:class:`DatePickerPanel`), a range of days or of datetimes across
up to three months (:class:`DateRangePickerPanel`), and a preset list
beside a month (:class:`PresetDatePicker`). Each is one value, worked out
from what its pieces hand it, so a page holds one ``State`` for the panel.

What lives here and what does not follows one rule: anything that needs
focus, scrolling, a repaint of part of a widget, or knows dates through
``Intl`` is an SDK primitive (the calendar, the wheel, the segments, the
button group, the card). What a panel holds, in what order, and how several
values make one is a Component in this module.

The module is compiled like any app module, so it keeps to the subset and
to a few rules of its own, each pinned by ``tests/ui/test_calendar_library.py``:

- **Public names only.** Every import is from ``workpeg.ui`` and in its
  ``__all__``, so the module could move into a library of its own by
  changing its import lines.
- **No shared base class.** The compiler does not carry a base class's
  methods into a subclass, so each Component holds its own few lines
  (``_label``, ``_today``) rather than inheriting them.
- **At most one State per Component, written once per event, and the
  caller's ``on_change`` called at most once per press.** Every state write
  renders the page.
- **Literal defaults.** Lists and dicts default to ``None`` and come from
  methods (``_default_presets``), because a module-level list or dict is
  invisible to the compiler.
- **Values are ISO strings and dicts of them** (``"2025-12-16"``,
  ``"14:30"``, ``{"start": …, "end": …}``), and the date logic is the
  ``dates`` capability, which runs in the page and, through its Python
  twin, under CPython: ``tests/ui/test_calendar_library_dualrun.py`` calls
  every pure method here both ways and requires the same answer.
- **Fixed words come from ``labels=``**, a dict read through ``_label``:
  a library cannot reach the page's Translations, so a page in another
  language passes its own words. A key is one word wherever it is read
  (``today`` is the quick dates' "Today" and the preset list's alike,
  ``time`` each panel's time row), and no two words share a key, so a
  panel hands its one dict to every block it holds.

``Row`` and ``Column`` take no ``style=``, so a block that needs a box
style (a width cap, a divider) puts its row in a ``Container`` that carries
it. A panel's optional row is a ``Container(row, visible=flag)`` too: a
child that is ``None`` does not compile, and a hidden flex item spends no
gap, so the card's 16px rhythm holds whichever rows are shown.
"""
from workpeg.ui import (Button, ButtonGroup, CalendarCard,
                        CalendarDatePicker, CalendarDateRangePicker, Column,
                        Component, Container, DateSegments, Row, Spacer,
                        State, Text, ToggleButton, ToggleGroup, Wrap, dates)


class QuickRanges(Component):
    """The design's quick-range row: plain actions with no selected state.

    Without children it is three buttons, **Today**, **Week** and
    **Monday**, each working out its value from today at the moment it is
    pressed (``current_date``, else today in ``time_zone``) and handing it
    to ``on_change``::

        QuickRanges(on_change=self.set_day)                 # a date
        QuickRanges(mode="range", on_change=self.set_span)  # a range

    ``mode="single"`` emits a date: today, a week from today, the next
    Monday. ``mode="range"`` emits a complete range: today alone, this
    week (by ``starting_day_of_week``, else the first day of ``locale``'s
    week, the day a calendar given that locale starts its rows on), and
    next Monday to its Sunday. With children, they are the row, the page's
    own Buttons each running its own handler::

        QuickRanges(Button("Tomorrow", on_click=self.tomorrow),
                    Button("Friday", on_click=self.friday))

    Labels: ``today``, ``week``, ``monday``, and ``quick_dates`` (the
    row's accessible name, "Quick dates").
    """

    def __init__(self, *children, on_change=None, mode="single",
                 current_date=None, time_zone=None,
                 starting_day_of_week=None, locale=None, labels=None):
        self.children = children
        self.on_change = on_change
        self.mode = mode
        self.current_date = current_date
        self.time_zone = time_zone
        self.starting_day_of_week = starting_day_of_week
        self.locale = locale
        self.labels = labels

    def _label(self, key, fallback):
        # labels come from a table row as often as from the page's source,
        # so any shape is read without a throw: a throw in build() stops
        # the whole page drawing, not just this row. Labels that are no
        # dict ("es", a list), and a word that is not text or is "" (a
        # translation not filled in, a number), are the English; drawn, a
        # None would read "None" in Python and "null" in a page.
        # str(x) == x is the subset's test for text (isinstance takes
        # only list), and .get is its test for a dict: on anything else it
        # throws in a page as it does in Python.
        try:
            words = self.labels.get(key, "") if self.labels else ""
        except Exception:
            return fallback
        return words if str(words) == words and words != "" else fallback

    def _today(self):
        # current_date is read as the calendar beside the row reads it, a
        # date or nothing: a datetime, or a day that does not exist, is
        # today, so the row and the calendar never have two todays.
        if dates.is_date(self.current_date):
            return self.current_date
        return dates.today(self.time_zone)

    def _first(self):
        # A first day that is not 1 to 7 ("1", 0, True) is the locale's, as
        # the calendar beside the row reads it, rather than a week with no
        # ends. next_weekday is the capability's own weekday check, asked
        # of a day far from either end of the calendar. The locale's is
        # this row's locale, read as the calendar reads its own: with the
        # page's language instead, a de-DE calendar on an en-US page drew
        # Monday-first rows while "Week" picked Sunday to Saturday, across
        # two of them.
        first = self.starting_day_of_week
        if first is not None and dates.next_weekday("2000-01-03", first):
            return first
        return dates.week_start(self.locale)

    def _value(self, which, today):
        """What the button ``which`` picks on ``today``: pure, so a test can
        hold it to the twin. None when ``today`` is not a date, or when
        either end of the range would fall past the calendar's last day:
        a press then picks nothing rather than half a range."""
        if not dates.is_date(today):
            return None
        span = self.mode == "range"
        if which == "week" and span:
            start = dates.start_of_week(today, self._first())
            end = dates.end_of_week(today, self._first())
            return {"start": start, "end": end} if start and end else None
        if which == "week":
            return dates.add_days(today, 7)
        if which == "monday":
            monday = dates.next_weekday(today, dates.MONDAY)
            sunday = dates.add_days(monday, 6)
            if span:
                return {"start": monday, "end": sunday} if sunday else None
            return monday
        if span:
            return {"start": today, "end": today}
        return today

    def _press(self, which):
        # Worked out now, not at render: a page left open past midnight
        # must not pick yesterday's "today".
        value = self._value(which, self._today())
        if value is not None and self.on_change:
            self.on_change(value)

    def build(self):
        if self.children:
            return ButtonGroup(*self.children, variant="tertiary-gray",
                               rounded=True,
                               label=self._label("quick_dates", "Quick dates"))
        return ButtonGroup(
            Button(self._label("today", "Today"),
                   on_click=lambda: self._press("today")),
            Button(self._label("week", "Week"),
                   on_click=lambda: self._press("week")),
            Button(self._label("monday", "Monday"),
                   on_click=lambda: self._press("monday")),
            variant="tertiary-gray", rounded=True,
            label=self._label("quick_dates", "Quick dates"),
        )


class DurationModes(Component):
    """The design's duration-mode row: a single choice of range length.

    A row of chips, ``0`` meaning exact dates and any other number a range
    of that many days, which a range picker takes as its ``range_length``::

        DurationModes(value=self.days, on_change=self.set_days)
        CalendarDateRangePicker(..., range_length=self.days or None)

    ``options`` is the list of lengths, whole days from 0 to 366
    (``[0, 1, 2]`` by default), and ``on_change`` receives the length
    pressed. It is one Tab stop, announced
    as a radio group: arrows move between the chips. Labels: ``exact``
    ("Exact dates"), ``day`` ("{n} day"), ``days`` ("{n} days") and
    ``duration`` (the row's accessible name, "Duration"); ``{n}`` is replaced
    by the number.
    """

    def __init__(self, value=0, on_change=None, options=None, labels=None):
        self.value = value
        self.on_change = on_change
        self.options = options
        self.labels = labels

    def _label(self, key, fallback):
        # As QuickRanges._label: any shape, never a throw, text or English.
        try:
            words = self.labels.get(key, "") if self.labels else ""
        except Exception:
            return fallback
        return words if str(words) == words and words != "" else fallback

    def _options(self):
        # A length a range picker cannot take (1.5, "7", True, None, more
        # than 366 days) is left out, and 7.0 from JSON is 7: a page writes
        # 7.0 as "7" and None as "null" where Python writes "7.0" and
        # "None", so the chips would read differently in each. add_days is
        # the capability's own whole-number check, which refuses a bool.
        # Options that cannot be walked at all (7) are the default, rather
        # than a throw in build() that stops the page drawing; a string or
        # a dict walks, in a page as in Python, to nothing a chip can be.
        try:
            return [int(n) for n in (self.options if self.options
                                     else [0, 1, 2])
                    if dates.add_days("2000-01-01", n) and 0 <= n <= 366]
        except Exception:
            return [0, 1, 2]

    def _fill(self, words, n):
        # Concatenation, not str.format: a label is the page's text, and
        # format would read any other brace in it as a field to fill.
        if "{n}" not in words:
            return words
        at = words.index("{n}")
        return words[:at] + str(n) + words[at + 3:]

    def _text(self, n):
        if n == 0:
            return self._label("exact", "Exact dates")
        if n == 1:
            return self._fill(self._label("day", "{n} day"), n)
        return self._fill(self._label("days", "{n} days"), n)

    def build(self):
        # The chip is a ToggleButton dressed as the design's large tag. The
        # toggle keeps a 1px transparent border (forced colours draw it),
        # which the tag has not, so the pad is a pixel short of the tag's
        # 6px to land the label where the tag's does; a focused tag takes
        # its hover fill under the ring, where a toggle keeps its resting
        # one; and a tag held down is tinted, its label the brand's, where
        # a toggle has no press look and showed its hover grey. The hover
        # fill is a resting value (:rest), so the press's can win over it:
        # a plain key is inline, and no state block overrides that.
        return ToggleGroup(
            *[ToggleButton(Text(self._text(n)), value=n, style={
                "--tgl-h": "32px", "--tgl-pad": "5px", "--tgl-gap": "8px",
                "--tgl-font": "var(--text-label-lg-size)", "--tgl-lh": "24px",
                "--toggle-btn-bg-default": "var(--btn-secondary-gray-bg)",
                "--toggle-btn-bg-selected": "var(--color-brand-secondary)",
                "--toggle-btn-label-default": "var(--color-text-primary)",
                "--toggle-btn-label-selected":
                    "var(--color-brand-on-secondary)",
                ":rest": {
                    "--toggle-btn-bg-hover": "var(--btn-secondary-gray-bg-hover)"},
                ":focus-visible": {
                    "--tgl-rest": "var(--btn-secondary-gray-bg-hover)"},
                ":active": {
                    "--toggle-btn-bg-hover": "var(--color-brand-secondary-subtle2)",
                    "--tgl-rest": "var(--color-brand-secondary-subtle2)",
                    "--tgl-fg": "var(--color-brand-secondary)"},
            }) for n in self._options()],
            value=self.value, on_change=self.on_change, spaced=True,
            label=self._label("duration", "Duration"),
            style={"gap": "8px", "flex-wrap": "wrap",
                   "max-width": "var(--calendar-row-max, none)"},
        )


class TimeRow(Component):
    """The design's ``.calendar-time``: a label beside a time pill.

    The pill is a ``DateSegments(kind="time", appearance="pill")``, so the
    time is typed a part at a time and its clock opens the wheel; ``value``
    is ``"HH:MM"`` (``"HH:MM:SS"`` with ``seconds=True``) or ``None``, and
    ``on_change`` receives one once every part is filled, and ``None`` once
    when a time it had stops being whole (a part cleared, or typed only in
    part), which a page keeping its time ignores, as the panels do::

        TimeRow("Start time", value=self.start, on_change=self.set_start)

    The zone's short name follows the time unless ``show_zone=False``.
    Inside a ``CalendarCard`` the row is capped at one month's width.
    """

    def __init__(self, label="Time", value=None, on_change=None,
                 seconds=False, use_24h_format=None, minute_interval=1,
                 show_zone=True, time_zone=None, locale=None,
                 first_time=None, last_time=None, disabled=False):
        self.label = label
        self.value = value
        self.on_change = on_change
        self.seconds = seconds
        self.use_24h_format = use_24h_format
        self.minute_interval = minute_interval
        self.show_zone = show_zone
        self.time_zone = time_zone
        self.locale = locale
        self.first_time = first_time
        self.last_time = last_time
        self.disabled = disabled

    def build(self):
        return Container(
            Row(Text(self.label,
                     style={"font-size": "var(--text-body-md-size)",
                            "font-weight": "var(--font-weight-medium)",
                            "color": "var(--color-text-primary)"}),
                Spacer(),
                DateSegments(kind="time", appearance="pill",
                             label=self.label, value=self.value,
                             on_change=self.on_change, seconds=self.seconds,
                             use_24h_format=self.use_24h_format,
                             minute_interval=self.minute_interval,
                             show_zone=self.show_zone,
                             time_zone=self.time_zone, locale=self.locale,
                             first_time=self.first_time,
                             last_time=self.last_time,
                             disabled=self.disabled),
                align="center", gap=12),
            style={"max-width": "var(--calendar-row-max, none)"},
        )


class PresetTile(Component):
    """The design's preset row (``.calendar-preset``), its content passed as
    slots the way ListTile takes them: ``title`` at the start, ``trailing``
    at the end in the quieter colour::

        PresetTile(title=Text("Tomorrow"), trailing=Text("Wed"),
                   selected=self.when == "tomorrow",
                   on_change=lambda on: self.pick("tomorrow"))

    It is a toggle button that stays pressed: ``selected`` is the state and
    ``on_change`` receives the new boolean, as a standalone ToggleButton's
    does. Each tile is its own Tab stop.
    """

    def __init__(self, title=None, trailing=None, selected=False,
                 on_change=None, disabled=False):
        self.title = title
        self.trailing = trailing
        self.selected = selected
        self.on_change = on_change
        self.disabled = disabled

    def build(self):
        # Ghost, so it is transparent until hovered; the pad is a pixel
        # short of the design's 12px for the toggle's own 1px border. The
        # trailing colour is a hook with its resting value as the fallback,
        # never set inline at rest: an inline key beats every state rule,
        # so ":selected" could not recolour it.
        return ToggleButton(
            self.title, Spacer(),
            Container(self.trailing, style={
                "color": "var(--cal-preset-trailing, "
                         "var(--color-text-placeholder))",
                "font-weight": "var(--font-weight-normal)"}),
            selected=self.selected, on_change=self.on_change,
            disabled=self.disabled, variant="ghost",
            style={"width": "100%", "border-radius": "16px",
                   "--tgl-h": "36px", "--tgl-pad": "11px", "--tgl-gap": "8px",
                   "--tgl-font": "var(--text-label-lg-size)",
                   "--tgl-lh": "20px",
                   "--toggle-btn-bg-hover": "var(--color-surface-raised)",
                   "--toggle-btn-bg-selected":
                       "var(--color-brand-secondary-subtle2)",
                   "--toggle-btn-label-default": "var(--color-text-primary)",
                   "--toggle-btn-label-selected": "var(--color-brand-secondary)",
                   ":selected": {
                       "--cal-preset-trailing": "var(--color-brand-secondary)"},
                   },
        )


class PresetList(Component):
    """A column of PresetTiles resolved against today: calendar.html's
    preset list (Today, In an hour, Tomorrow, This weekend, Next weekend,
    In 2 weeks, In 4 weeks).

    ``value`` is a datetime (``time=True``, the default) or a date, and
    ``on_change`` receives the preset's value, worked out again at the
    moment it is pressed::

        PresetList(value=self.when, on_change=self.set_when)

    A preset is a dict with ``id`` and ``label`` (text; anything else in the
    list is left out) and one of: ``days``, an offset from today;
    ``minutes``, that much time from now, counted as time passing, so
    across a change of the clocks "In an hour" is still an hour away (a
    time preset); ``weekday`` (1 for Monday to 7 for Sunday), that day on
    or after today, plus ``weeks`` whole weeks::

        presets=[{"id": "tomorrow", "label": "Tomorrow", "days": 1},
                 {"id": "soon", "label": "In 30 minutes", "minutes": 30},
                 {"id": "friday", "label": "Friday", "weekday": 5}]

    A date preset keeps the time of the current value, or ``default_time``.
    The trailing text is the time for a time preset, the short weekday
    within a week of today and the month and day after that. The tile shown
    pressed is worked out from the value, never stored: the first time
    preset whose datetime is the value, else the first date preset on its
    day. With ``time=False`` the value is a date and time presets are left
    out. ``divided=True`` draws the divider the preset picker puts between
    the list and its month. Labels: each default preset's ``id``.
    """

    def __init__(self, value=None, on_change=None, presets=None, time=True,
                 current_date=None, time_zone=None, locale=None,
                 default_time="00:00", divided=False, labels=None):
        self.value = value
        self.on_change = on_change
        self.presets = presets
        self.time = time
        self.current_date = current_date
        self.time_zone = time_zone
        self.locale = locale
        self.default_time = default_time
        self.divided = divided
        self.labels = labels

    def _label(self, key, fallback):
        # As QuickRanges._label: any shape, never a throw, text or English.
        try:
            words = self.labels.get(key, "") if self.labels else ""
        except Exception:
            return fallback
        return words if str(words) == words and words != "" else fallback

    def _today(self):
        # As QuickRanges._today: a date or nothing, as the calendar reads it.
        if dates.is_date(self.current_date):
            return self.current_date
        return dates.today(self.time_zone)

    def _now(self):
        """Now as an instant, epoch milliseconds to the minute.

        An instant, not the wall clock's reading: on the night the clocks
        go back, 01:30 comes twice, and only the instant says which, so
        only from it is "In an hour" an hour away. Read in UTC, where no
        minute repeats. With current_date (a demo, a test) it is the
        clock's time on that day, so "In an hour" lands on the day "Today"
        does."""
        if dates.is_date(self.current_date):
            return dates.to_epoch(
                dates.combine(self.current_date, dates.now(self.time_zone)),
                self.time_zone)
        return dates.to_epoch(dates.now("UTC"), "UTC")

    def _default_presets(self):
        return [
            {"id": "today", "label": self._label("today", "Today"),
             "days": 0},
            {"id": "in_an_hour",
             "label": self._label("in_an_hour", "In an hour"), "minutes": 60},
            {"id": "tomorrow", "label": self._label("tomorrow", "Tomorrow"),
             "days": 1},
            {"id": "this_weekend",
             "label": self._label("this_weekend", "This weekend"),
             "weekday": 6},
            {"id": "next_weekend",
             "label": self._label("next_weekend", "Next weekend"),
             "weekday": 6, "weeks": 1},
            {"id": "in_2_weeks",
             "label": self._label("in_2_weeks", "In 2 weeks"), "days": 14},
            {"id": "in_4_weeks",
             "label": self._label("in_4_weeks", "In 4 weeks"), "days": 28},
        ]

    def _usable(self, p):
        """Whether ``p`` is a preset a tile can be made of: a dict whose
        ``id`` and ``label`` are text. Presets may come from a table row,
        and anything else there (a string, a number, a dict without its id)
        would throw in build() and stop the page drawing, or give a tile
        whose key is undefined in a page and a KeyError in Python."""
        # .get is the dict test, throwing on anything else on both sides;
        # str(x) == x the text test.
        try:
            pid = p.get("id")
            label = p.get("label")
        except Exception:
            return False
        return str(pid) == pid and pid != "" and str(label) == label

    def _presets(self):
        # Presets that cannot be walked at all (5) are the default seven;
        # a list keeps the presets in it that a tile can be made of.
        try:
            given = [p for p in (self.presets if self.presets
                                 else self._default_presets())
                     if self._usable(p)]
        except Exception:
            given = self._default_presets()
        # A date has no hour to hold "in an hour", and resolved to its day
        # it would be a second "today".
        if self.time:
            return given
        return [p for p in given if "minutes" not in p]

    def _resolve(self, p, today, now):
        """The value preset ``p`` stands for on ``today`` at ``now`` (an
        instant, as ``_now`` gives it): pure, so a test can hold it to the
        twin."""
        if "minutes" in p:
            # Minutes from now are time passing, so the instant moves, not
            # the wall clock: on the night the clocks go back, "In an hour"
            # at 01:30 is 01:30 again, and on the night they go forward it
            # is never a time the zone skips. add_minutes is the
            # whole-number check, made before anything multiplies the
            # count (60000 * "1" is a number in a page and a string in
            # Python), and it bounds the count to the calendar's years.
            if not dates.add_minutes(dates.from_epoch(now, "UTC"),
                                     p["minutes"]):
                return None
            moved = dates.from_epoch(now + p["minutes"] * 60000,
                                     self.time_zone)
            return moved[:16] if moved else None
        if "weekday" in p:
            # One day a week goes on first, so add_days checks ``weeks`` is
            # a whole number before anything multiplies it, then the other
            # six: ``7 * "1"`` is 7 in a page but "1111111" in Python, and
            # ``7 * None`` is 0 in a page but a TypeError in Python.
            weeks = p.get("weeks", 0)
            on = dates.add_days(dates.next_weekday(today, p["weekday"], True),
                                weeks)
            day = dates.add_days(on, 6 * weeks) if on else None
        else:
            day = dates.add_days(today, p.get("days", 0))
        if not self.time:
            return day
        return dates.combine(day, dates.time_of(self.value) or self.default_time)

    def _trail(self, p, today, now):
        value = self._resolve(p, today, now)
        if not value:
            return ""
        if "minutes" in p:
            return dates.format(value, "time", self.locale)
        near = abs(dates.days_between(today, value)) < 7
        return dates.format(value, "weekday_short" if near else "month_day",
                            self.locale)

    def _match(self, today, now):
        """The id of the preset the value is: the first time preset on its
        whole datetime, else the first date preset on its day."""
        if not self.value:
            return None
        timed = next((p["id"] for p in self._presets() if "minutes" in p
                      and self._resolve(p, today, now) == self.value), None)
        if timed is not None:
            return timed
        day = dates.date_of(self.value)
        return next((p["id"] for p in self._presets() if "minutes" not in p
                     and day is not None
                     and dates.date_of(self._resolve(p, today, now)) == day),
                    None)

    def _selected_id(self):
        return self._match(self._today(), self._now())

    def _rows(self):
        """What each tile shows, worked out once a render: its id, its
        words and whether it is the one pressed. The pressed preset is
        found once for the list; found once a tile, as it was, every
        preset was resolved once for every tile, on every render of the
        page (2,000 presets took five seconds a press)."""
        today = self._today()
        now = self._now()
        on = self._match(today, now)
        return [{"id": p["id"], "label": p["label"],
                 "trail": self._trail(p, today, now), "on": p["id"] == on}
                for p in self._presets()]

    def _pick(self, pid):
        today = self._today()
        now = self._now()
        # A press on the tile already shown pressed changes nothing, as a
        # single-select calendar ignores its picked day pressed again.
        if pid == self._match(today, now):
            return
        p = next((x for x in self._presets() if x["id"] == pid), None)
        value = self._resolve(p, today, now) if p else None
        if value and self.on_change:
            self.on_change(value)

    def build(self):
        # Each tile's lambda is its own preset's: the comprehension compiles
        # to a callback per item, so ``r`` is that item's (a lambda may not
        # take a default argument to pin it, as CPython would need). The
        # width and the divider are read through the card's narrow form: a
        # row card on a phone (pegment.css, .calendar-preset-picker) stacks
        # the list above the month, as wide as the card, with no divider.
        return Container(
            Column(*[PresetTile(
                title=Text(r["label"]), trailing=Text(r["trail"]),
                selected=r["on"], on_change=lambda on: self._pick(r["id"]),
                key=r["id"]) for r in self._rows()], gap=6),
            style={"width": "var(--pg-preset-w, 224px)", "flex-shrink": "0",
                   "padding-inline-end": ("var(--pg-preset-pad, 12px)"
                                          if self.divided else "0"),
                   "border-inline-end": (
                       "var(--pg-preset-rule, 1px solid "
                       "var(--color-border-subtle))"
                       if self.divided else "none")},
        )


class RangeSummary(Component):
    """The design's ``.calendar-range-summary``: the range picked, in words.

    ``value`` is a range dict (of dates or datetimes); the summary shows
    "Selected: Dec 16, 2025 – Dec 24, 2025", the end in bold, and nothing at
    all until a start is picked (or for a value that is no range dict).
    While the range is open (``end`` is ``None``) it shows the start
    alone::

        RangeSummary(value=self.span)
        RangeSummary(Text("Stay:"), value=self.span, style_name="long")

    Children replace the "Selected:" lead. ``style_name`` is a
    ``dates.format`` style and ``locale`` its language. Labels:
    ``selected``.
    """

    def __init__(self, *children, value=None, style_name="medium",
                 locale=None, labels=None):
        self.children = children
        self.value = value
        self.style_name = style_name
        self.locale = locale
        self.labels = labels

    def _label(self, key, fallback):
        # As QuickRanges._label: any shape, never a throw, text or English.
        try:
            words = self.labels.get(key, "") if self.labels else ""
        except Exception:
            return fallback
        return words if str(words) == words and words != "" else fallback

    def _end(self, end):
        """One end of the range as given, or None for an end not picked,
        one that is not an ISO date or datetime (an instant's number would
        otherwise be formatted as a date), or a value that is no range dict
        at all."""
        # A value from a table row may be a string or a list, which has no
        # .get: in a page that throw would stop the whole page drawing.
        try:
            v = self.value.get(end)
        except Exception:
            return None
        return v if dates.is_date(v) or dates.is_datetime(v) else None

    def _text(self, end):
        """One end of the range, in words, or "" for an end there is not."""
        return dates.format(self._end(end), self.style_name,
                            self.locale) or ""

    def build(self):
        # A Wrap, not a Row: the design's summary is a sentence, which on a
        # phone runs on to a second line, where a Row squeezes each date
        # into a narrow column broken over two lines. A date that does not
        # fit moves down whole; the lines sit as close as a paragraph's.
        # The line is the design page's own 1.5, which its paragraph takes
        # from the page and a peg's text does not: at a peg's "normal" the
        # summary stood 0.7px taller, and so did every panel holding one.
        return Container(
            Wrap(*self.children,
                 Text(self._label("selected", "Selected:"),
                      visible=not self.children),
                 Text(self._text("start")),
                 Text("–", visible=self._text("end") != ""),
                 Text(self._text("end"), weight="semibold",
                      style={"color": "var(--color-text-primary)"},
                      visible=self._text("end") != ""),
                 spacing=4, run_spacing=0),
            visible=self._text("start") != "",
            style={"font-size": "var(--text-body-md-size)",
                   "line-height": "1.5",
                   "color": "var(--color-text-secondary)"},
        )


# ── the assembled panels ──────────────────────────────────────────────────
#
# Each panel is one value, worked out from what its pieces hand it, and
# calls the page's on_change once per press. The calendar's keywords are
# handed to the calendar as they came (a None arriving there means "not
# given"), and the time row's to the time row. A Component takes no
# **kwargs, so each is written out, with the default its widget has: None
# for the calendar's, and the time row's own True and 1 for show_zone and
# minute_interval, since a None there would turn the zone off and is no
# step at all.


class DatePickerPanel(Component):
    """calendar.html's Picker Panel for one date and its time: the quick
    dates, a flat month and the time row in one card.

    ``value`` is a datetime, ``"2025-12-16T10:30"`` (a date with
    ``time=False``), and ``on_change`` receives the new one::

        DatePickerPanel(value=self.due, on_change=self.set_due)

    A day picked, on the month or from the quick dates, keeps the time
    already set, else ``default_time``; a time typed keeps the day, else
    today. The calendar's keywords (``first_date``, ``last_date``,
    ``current_date``, ``selectable_day_predicate``, ``disabled_dates``,
    ``disabled_weekdays``, ``markers`` or ``event_loader``,
    ``starting_day_of_week``, ``locale``, ``time_zone``) are the
    calendar's, and ``seconds``, ``use_24h_format``, ``minute_interval``
    and ``show_zone`` the time row's. ``quick_ranges=False`` leaves the
    quick dates out, ``time=False`` the time row. The panel holds no
    state. Labels: ``time``, and the quick dates' own.
    """

    def __init__(self, value=None, on_change=None, time=True, seconds=False,
                 quick_ranges=True, default_time="00:00", labels=None,
                 first_date=None, last_date=None, current_date=None,
                 selectable_day_predicate=None, disabled_dates=None,
                 disabled_weekdays=None, markers=None, event_loader=None,
                 starting_day_of_week=None, locale=None, time_zone=None,
                 use_24h_format=None, minute_interval=1, show_zone=True):
        self.value = value
        self.on_change = on_change
        self.time = time
        self.seconds = seconds
        self.quick_ranges = quick_ranges
        self.default_time = default_time
        self.labels = labels
        self.first_date = first_date
        self.last_date = last_date
        self.current_date = current_date
        self.selectable_day_predicate = selectable_day_predicate
        self.disabled_dates = disabled_dates
        self.disabled_weekdays = disabled_weekdays
        self.markers = markers
        self.event_loader = event_loader
        self.starting_day_of_week = starting_day_of_week
        self.locale = locale
        self.time_zone = time_zone
        self.use_24h_format = use_24h_format
        self.minute_interval = minute_interval
        self.show_zone = show_zone

    def _label(self, key, fallback):
        # As QuickRanges._label: any shape, never a throw, text or English.
        try:
            words = self.labels.get(key, "") if self.labels else ""
        except Exception:
            return fallback
        return words if str(words) == words and words != "" else fallback

    def _today(self):
        # As QuickRanges._today: a date or nothing, as the calendar reads it.
        if dates.is_date(self.current_date):
            return self.current_date
        return dates.today(self.time_zone)

    def _value(self, day, at):
        """What the panel hands on for the date ``day`` at the time ``at``,
        either None for the value's own: a day picked keeps the time already
        set, else ``default_time``, and a time typed keeps the day, else
        today. With ``time=False``, the day. None when the parts make no
        datetime (a ``default_time`` that is no ISO time). Pure, so a test
        can hold it to the twin."""
        day = day or dates.date_of(self.value) or self._today()
        if not self.time:
            return day
        return dates.combine(day, at or dates.time_of(self.value)
                             or self.default_time)

    def _on_date(self, d):
        self._send(self._value(d, None))

    def _on_time(self, t):
        # A time cleared, or typed only in part, arrives as None: the row
        # keeps what is typed, and the value keeps its time until the new
        # one is whole, rather than losing it.
        if t:
            self._send(self._value(None, t))

    def _send(self, value):
        if value and self.on_change:
            self.on_change(value)

    def build(self):
        return CalendarCard(
            Container(QuickRanges(on_change=self._on_date,
                                  current_date=self.current_date,
                                  time_zone=self.time_zone,
                                  starting_day_of_week=self.starting_day_of_week,
                                  locale=self.locale, labels=self.labels),
                      visible=self.quick_ranges),
            CalendarDatePicker(
                value=dates.date_of(self.value), on_change=self._on_date,
                surface="flat", first_date=self.first_date,
                last_date=self.last_date, current_date=self.current_date,
                selectable_day_predicate=self.selectable_day_predicate,
                disabled_dates=self.disabled_dates,
                disabled_weekdays=self.disabled_weekdays,
                markers=self.markers, event_loader=self.event_loader,
                starting_day_of_week=self.starting_day_of_week,
                locale=self.locale, time_zone=self.time_zone),
            Container(TimeRow(self._label("time", "Time"),
                              value=dates.time_of(self.value),
                              on_change=self._on_time, seconds=self.seconds,
                              use_24h_format=self.use_24h_format,
                              minute_interval=self.minute_interval,
                              show_zone=self.show_zone,
                              time_zone=self.time_zone, locale=self.locale),
                      visible=self.time),
        )


class DateRangePickerPanel(Component):
    """calendar.html's Range Picker: the quick dates, one to three flat
    months under one pair of arrows, the start and end times, the duration
    chips and a summary of the range, in one card.

    ``value`` is a range, ``{"start": "2025-12-16", "end": "2025-12-24"}``,
    of datetimes with ``times=True``, and ``on_change`` receives the new
    one: on the first press of a range, open (``"end": None``), and on the
    second, whole::

        DateRangePickerPanel(value=self.stay, on_change=self.set_stay,
                             months=2, times=True, durations=[0, 1, 2, 7],
                             summary=True)

    With ``times=True`` a day picked keeps its end's time, else
    ``default_start_time`` or ``default_end_time``, and a time typed keeps
    the days (a start time with no range picked starts one today). An end
    time needs an end day: while there is none (the range open, or nothing
    picked) the time is held, shown in the end row, and given to the end
    day picked next, and so is the end's time when the days are picked
    again. An end never comes before its start: on one day, the end time is
    held to the start time, and a start moved past the end takes the end
    with it.

    ``durations`` (whole days, 0 for exact dates) adds the chips; the one
    chosen is the calendar's ``range_length`` from the next press, never a
    rewrite of the range already picked, and only while the page still
    offers that chip.
    ``summary=True`` adds the summary, ``quick_ranges=False`` leaves the
    quick dates out. The calendar's keywords are the calendar's and the
    time keywords the time rows', as for DatePickerPanel. Labels:
    ``start_time``, ``end_time``, and those of the blocks it holds.
    """

    # The panel's own state, in one field: the duration chip chosen, and an
    # end time waiting for its end day (one typed while the range is open,
    # or the end's own when the days are picked again), which the open
    # range handed to the page has no end to carry.
    held = State({"duration": 0, "end_time": None})

    def __init__(self, value=None, on_change=None, months=1, times=False,
                 seconds=False, durations=None, summary=False,
                 quick_ranges=True, default_start_time="00:00",
                 default_end_time="23:59", labels=None, first_date=None,
                 last_date=None, current_date=None,
                 selectable_day_predicate=None, disabled_dates=None,
                 disabled_weekdays=None, markers=None, event_loader=None,
                 starting_day_of_week=None, locale=None, time_zone=None,
                 use_24h_format=None, minute_interval=1, show_zone=True):
        self.value = value
        self.on_change = on_change
        self.months = months
        self.times = times
        self.seconds = seconds
        self.durations = durations
        self.summary = summary
        self.quick_ranges = quick_ranges
        self.default_start_time = default_start_time
        self.default_end_time = default_end_time
        self.labels = labels
        self.first_date = first_date
        self.last_date = last_date
        self.current_date = current_date
        self.selectable_day_predicate = selectable_day_predicate
        self.disabled_dates = disabled_dates
        self.disabled_weekdays = disabled_weekdays
        self.markers = markers
        self.event_loader = event_loader
        self.starting_day_of_week = starting_day_of_week
        self.locale = locale
        self.time_zone = time_zone
        self.use_24h_format = use_24h_format
        self.minute_interval = minute_interval
        self.show_zone = show_zone

    def _label(self, key, fallback):
        # As QuickRanges._label: any shape, never a throw, text or English.
        try:
            words = self.labels.get(key, "") if self.labels else ""
        except Exception:
            return fallback
        return words if str(words) == words and words != "" else fallback

    def _today(self):
        # As QuickRanges._today: a date or nothing, as the calendar reads it.
        if dates.is_date(self.current_date):
            return self.current_date
        return dates.today(self.time_zone)

    def _end(self, which):
        """One end of the value as given, an ISO date or datetime, or None:
        an end not picked, or a value that is no range dict (a range
        field's ``"start/end"`` text, a list), which has no ``.get`` and
        would otherwise throw in build() and stop the page drawing."""
        try:
            v = self.value.get(which)
        except Exception:
            return None
        return v if dates.is_date(v) or dates.is_datetime(v) else None

    def _dates(self):
        """The range as the calendar draws it: the value's days, or None."""
        start = dates.date_of(self._end("start"))
        return {"start": start,
                "end": dates.date_of(self._end("end"))} if start else None

    def _end_time(self):
        """The end's own time: the value's end's, else, while there is no
        end day, the time held for it (None for none)."""
        return dates.time_of(self._end("end")) or self.held.get("end_time")

    def _range(self, start, end, at_start, at_end):
        """The range the panel hands on: the days ``start`` and ``end`` (None
        while the range is open), at the times ``at_start`` and ``at_end``,
        each None for its end's own time (``_end_time``), else its default.
        An end that would come before its start (one day picked twice under
        times that cross, or a start time typed past the end) takes the
        start's datetime. None when the parts make no start. Pure but for
        the end time held in the panel's State, so a test can hold it to the
        twin with that State set."""
        if not self.times:
            return {"start": start, "end": end}
        first = dates.combine(start, at_start
                              or dates.time_of(self._end("start"))
                              or self.default_start_time)
        last = dates.combine(end, at_end or self._end_time()
                             or self.default_end_time) if end else None
        if not first:
            return None
        return {"start": first, "end": last if not last or last >= first
                else first}

    def _one_day(self):
        # Whether the range starts and ends on one day, where the end time
        # may not come before the start time.
        day = dates.date_of(self._end("start"))
        return day is not None and day == dates.date_of(self._end("end"))

    def _length(self):
        """The calendar's ``range_length``: the chip chosen, while the page
        still offers it. One the page has taken away (``durations`` None,
        or a list without it) fixes nothing, as no control on screen could
        undo it. Only a list is asked: in a page ``in`` reads a string's
        letters and a dict's keys, where "7" and {"7": 1} would hold 7."""
        n = self.held.get("duration")
        return (n if n and isinstance(self.durations, list)
                and n in self.durations else None)

    def _hold(self, duration, end_time):
        # The one state write, at most once an event. A press on the month
        # writes it beside the page's on_change, and the calendar renders
        # the two once; a chip or an end time held writes it alone.
        self.held = {"duration": duration, "end_time": end_time}

    def _on_range(self, r):
        # Days picked again: the first press hands on an open range, with
        # no end to keep the end's time on, so the end's time is held for
        # the second press; without it, 18:00 came back as default_end_time.
        # Only beside a range sent: a press that makes none changes nothing.
        value = self._range(r["start"], r["end"], None, None)
        if value and not r["end"]:
            self._hold(self.held.get("duration"), self._end_time())
        self._send(value)

    def _on_start_time(self, t):
        # As DatePickerPanel._on_time, a time not whole is no change.
        if t:
            self._send(self._range(
                dates.date_of(self._end("start")) or self._today(),
                dates.date_of(self._end("end")), t, None))

    def _on_end_time(self, t):
        # An end time needs an end day. With none yet it is held for the
        # day picked next, the range left as it is: put on the start's day,
        # a time earlier than the start's became the start's, and the
        # range closed, so the next day pressed began a new one.
        if t and self._end("end"):
            self._send(self._range(
                dates.date_of(self._end("start")) or self._today(),
                dates.date_of(self._end("end")), None, t))
        elif t:
            self._hold(self.held.get("duration"), t)

    def _send(self, value):
        if value and self.on_change:
            self.on_change(value)

    def _set_duration(self, n):
        # The length applies from the next press on the calendar, and the
        # range already picked stays.
        self._hold(n, self.held.get("end_time"))

    def build(self):
        return CalendarCard(
            Container(QuickRanges(mode="range", on_change=self._on_range,
                                  current_date=self.current_date,
                                  time_zone=self.time_zone,
                                  starting_day_of_week=self.starting_day_of_week,
                                  locale=self.locale, labels=self.labels),
                      visible=self.quick_ranges),
            CalendarDateRangePicker(
                value=self._dates(), on_change=self._on_range,
                months=self.months, surface="flat",
                range_length=self._length(),
                first_date=self.first_date, last_date=self.last_date,
                current_date=self.current_date,
                selectable_day_predicate=self.selectable_day_predicate,
                disabled_dates=self.disabled_dates,
                disabled_weekdays=self.disabled_weekdays,
                markers=self.markers, event_loader=self.event_loader,
                starting_day_of_week=self.starting_day_of_week,
                locale=self.locale, time_zone=self.time_zone),
            Container(TimeRow(self._label("start_time", "Start time"),
                              value=dates.time_of(self._end("start")),
                              on_change=self._on_start_time,
                              seconds=self.seconds,
                              use_24h_format=self.use_24h_format,
                              minute_interval=self.minute_interval,
                              show_zone=self.show_zone,
                              time_zone=self.time_zone, locale=self.locale),
                      visible=self.times),
            Container(TimeRow(self._label("end_time", "End time"),
                              value=self._end_time(),
                              on_change=self._on_end_time,
                              seconds=self.seconds,
                              use_24h_format=self.use_24h_format,
                              minute_interval=self.minute_interval,
                              show_zone=self.show_zone,
                              time_zone=self.time_zone, locale=self.locale,
                              first_time=dates.time_of(self._end("start"))
                              if self._one_day() else None),
                      visible=self.times),
            Container(DurationModes(value=self.held.get("duration"),
                                    on_change=self._set_duration,
                                    options=self.durations,
                                    labels=self.labels),
                      visible=self.durations),
            Container(RangeSummary(value=self.value, locale=self.locale,
                                   labels=self.labels),
                      visible=self.summary),
        )


class PresetDatePicker(Component):
    """calendar.html's Preset Picker: a list of presets beside a flat month
    and the time row, in one card laid out as a row.

    ``value`` is a datetime (a date with ``time=False``) and ``on_change``
    receives the new one, from a preset (worked out when it is pressed, see
    PresetList), a day picked (keeping the time already set, else
    ``default_time``) or a time typed (keeping the day, else today)::

        PresetDatePicker(value=self.remind, on_change=self.set_remind)

    ``presets`` are PresetList's (the design's seven by default). The time
    row shows seconds unless ``seconds=False``, as the design draws it.
    The calendar's keywords are the calendar's (and today, the zone and
    the locale the list's too), and the time keywords the time row's, as
    for DatePickerPanel. The panel holds no state. Labels: ``time``, and
    the presets'.
    """

    def __init__(self, value=None, on_change=None, presets=None, time=True,
                 seconds=True, default_time="00:00", labels=None,
                 first_date=None, last_date=None, current_date=None,
                 selectable_day_predicate=None, disabled_dates=None,
                 disabled_weekdays=None, markers=None, event_loader=None,
                 starting_day_of_week=None, locale=None, time_zone=None,
                 use_24h_format=None, minute_interval=1, show_zone=True):
        self.value = value
        self.on_change = on_change
        self.presets = presets
        self.time = time
        self.seconds = seconds
        self.default_time = default_time
        self.labels = labels
        self.first_date = first_date
        self.last_date = last_date
        self.current_date = current_date
        self.selectable_day_predicate = selectable_day_predicate
        self.disabled_dates = disabled_dates
        self.disabled_weekdays = disabled_weekdays
        self.markers = markers
        self.event_loader = event_loader
        self.starting_day_of_week = starting_day_of_week
        self.locale = locale
        self.time_zone = time_zone
        self.use_24h_format = use_24h_format
        self.minute_interval = minute_interval
        self.show_zone = show_zone

    def _label(self, key, fallback):
        # As QuickRanges._label: any shape, never a throw, text or English.
        try:
            words = self.labels.get(key, "") if self.labels else ""
        except Exception:
            return fallback
        return words if str(words) == words and words != "" else fallback

    def _today(self):
        # As QuickRanges._today: a date or nothing, as the calendar reads it.
        if dates.is_date(self.current_date):
            return self.current_date
        return dates.today(self.time_zone)

    def _value(self, day, at):
        """As DatePickerPanel._value: the day and the time, either None for
        the value's own, else today and ``default_time``. Pure."""
        day = day or dates.date_of(self.value) or self._today()
        if not self.time:
            return day
        return dates.combine(day, at or dates.time_of(self.value)
                             or self.default_time)

    def _on_date(self, d):
        self._send(self._value(d, None))

    def _on_time(self, t):
        # As DatePickerPanel._on_time, a time not whole is no change.
        if t:
            self._send(self._value(None, t))

    def _send(self, value):
        if value and self.on_change:
            self.on_change(value)

    def build(self):
        return CalendarCard(
            PresetList(value=self.value, on_change=self.on_change,
                       presets=self.presets, time=self.time,
                       current_date=self.current_date,
                       time_zone=self.time_zone, locale=self.locale,
                       default_time=self.default_time, divided=True,
                       labels=self.labels),
            Column(
                CalendarDatePicker(
                    value=dates.date_of(self.value), on_change=self._on_date,
                    surface="flat", first_date=self.first_date,
                    last_date=self.last_date, current_date=self.current_date,
                    selectable_day_predicate=self.selectable_day_predicate,
                    disabled_dates=self.disabled_dates,
                    disabled_weekdays=self.disabled_weekdays,
                    markers=self.markers, event_loader=self.event_loader,
                    starting_day_of_week=self.starting_day_of_week,
                    locale=self.locale, time_zone=self.time_zone),
                Container(TimeRow(self._label("time", "Time"),
                                  value=dates.time_of(self.value),
                                  on_change=self._on_time,
                                  seconds=self.seconds,
                                  use_24h_format=self.use_24h_format,
                                  minute_interval=self.minute_interval,
                                  show_zone=self.show_zone,
                                  time_zone=self.time_zone,
                                  locale=self.locale),
                          visible=self.time),
                gap=16),
            direction="row",
        )
